from pathlib import Path

p = Path('src/pages/CoachAppWhiteboardStage2.tsx')
s = p.read_text()

anchor = "  const[playerDrawerOpen,setPlayerDrawerOpen]=useState(false)"
if "const[playerSearch,setPlayerSearch]" not in s:
    s = s.replace(anchor, anchor + "\n  const[playerSearch,setPlayerSearch]=useState('')\n  const[playerSelection,setPlayerSelection]=useState<string[]>([])\n  const[selectedMagnetId,setSelectedMagnetId]=useState('')")

marker = "  function optionOnField(id:string){return state.magnets.some(item=>item.id===id)}"
if "function filteredPlayerOptions" not in s:
    replacement = marker + "\n  function filteredPlayerOptions(){const source=playerTab==='US'?ourPlayers:oppositionPlayers;const q=playerSearch.trim().toLowerCase();return q?source.filter(option=>`${option.name} ${option.number??''}`.toLowerCase().includes(q)):source}\n  function togglePlayerSelection(id:string){setPlayerSelection(current=>current.includes(id)?current.filter(item=>item!==id):[...current,id])}\n  function addSelectedPlayers(){const source=[...ourPlayers,...oppositionPlayers];const selected=source.filter(option=>playerSelection.includes(option.id));if(!selected.length)return;let next=[...state.magnets];selected.forEach((option,index)=>{if(next.some(item=>item.id===option.id))return;next.push({id:option.id,name:option.name,number:option.number,team:option.team,x:option.team==='US'?7:93,y:22+((next.length+index)%6)*10})});updateState({...state,magnets:next});setPlayerSelection([])}\n  function quickSetup(usCount:number,themCount:number){const ours=ourPlayers.slice(0,usCount);const them=oppositionPlayers.slice(0,themCount);const magnets:Magnet[]=[];ours.forEach((option,index)=>magnets.push({id:option.id,name:option.name,number:option.number,team:'US',x:38,y:44+index*10}));them.forEach((option,index)=>magnets.push({id:option.id,name:option.name,number:option.number,team:'THEM',x:62,y:44+index*10}));updateState({...state,magnets})}\n  function selectMagnet(id:string){setSelectedMagnetId(id)}\n  function updateSelectedMagnet(changes:Partial<Pick<Magnet,'name'|'number'|'team'>>){if(!selectedMagnetId)return;updateState({...state,magnets:state.magnets.map(item=>item.id===selectedMagnetId?{...item,...changes}:item)})}\n  function duplicateSelectedMagnet(){const magnet=state.magnets.find(item=>item.id===selectedMagnetId);if(!magnet)return;const copy={...magnet,id:`copy-${crypto.randomUUID()}`,x:Math.min(96,magnet.x+5),y:Math.min(96,magnet.y+5)};updateState({...state,magnets:[...state.magnets,copy]});setSelectedMagnetId(copy.id)}\n  function removeSelectedMagnet(){if(!selectedMagnetId)return;updateState({...state,magnets:state.magnets.filter(item=>item.id!==selectedMagnetId)});setSelectedMagnetId('')}"
    s = s.replace(marker, replacement)

old = "function startMagnet(event:React.PointerEvent<SVGGElement>,id:string){if(tool!=='MOVE'||playing)return;event.stopPropagation();snapshot();setDragging(id);event.currentTarget.setPointerCapture?.(event.pointerId)}"
new = "function startMagnet(event:React.PointerEvent<SVGGElement>,id:string){if(tool!=='MOVE'||playing)return;event.stopPropagation();selectMagnet(id);snapshot();setDragging(id);event.currentTarget.setPointerCapture?.(event.pointerId)}"
s = s.replace(old, new)

start = s.find("    {playerDrawerOpen&&<div className=\"cawb2-modal\">")
end = s.find("    {analysisOpen&&", start)
if start != -1 and end != -1:
    drawer = '''    {playerDrawerOpen&&<><button className="player-drawer-backdrop" aria-label="Close player library" onClick={()=>setPlayerDrawerOpen(false)}/><aside className="player-drawer"><header><div><span>PLAYER LIBRARY</span><h2>Build this frame</h2><p>{state.magnets.filter(m=>m.team==='US').length} ours · {state.magnets.filter(m=>m.team==='THEM').length} opposition on field</p></div><button onClick={()=>setPlayerDrawerOpen(false)}><X/></button></header><div className="player-tabs"><button className={playerTab==='US'?'active':''} onClick={()=>{setPlayerTab('US');setPlayerSelection([])}}>Our Team</button><button className={playerTab==='THEM'?'active':''} onClick={()=>{setPlayerTab('THEM');setPlayerSelection([])}}>Opposition</button><button className={playerTab==='GENERIC'?'active':''} onClick={()=>{setPlayerTab('GENERIC');setPlayerSelection([])}}>Generic</button></div>{playerTab!=='GENERIC'?<><input className="player-search" value={playerSearch} onChange={e=>setPlayerSearch(e.target.value)} placeholder="Search player or number"/><div className="quick-setups"><button onClick={()=>quickSetup(1,1)}>1 v 1</button><button onClick={()=>quickSetup(2,1)}>2 v 1</button><button onClick={()=>quickSetup(2,2)}>2 v 2</button><button onClick={()=>quickSetup(3,2)}>3 v 2</button></div><div className="player-actions"><button onClick={()=>addEntireTeam(playerTab)}>Add Entire Team</button><button onClick={()=>removeTeam(playerTab)}>Remove This Team</button></div><div className="player-grid">{filteredPlayerOptions().map(option=>{const onField=optionOnField(option.id);const selected=playerSelection.includes(option.id);return <button key={option.id} className={`${onField?'selected':''} ${selected?'queued':''}`} onClick={()=>togglePlayerSelection(option.id)}><b>{option.number??'–'}</b><span>{option.name}</span><small>{onField?'On field':selected?'Selected':'Tap to select'}</small></button>})}</div><footer><button className="secondary" onClick={()=>setPlayerSelection([])}>Clear selection</button><button className="primary" disabled={!playerSelection.length} onClick={addSelectedPlayers}>Add selected ({playerSelection.length})</button></footer></>:<div className="generic-actions"><button onClick={()=>openDialog('GENERIC','Player','', 'US')}>+ Generic Our Player</button><button onClick={()=>openDialog('GENERIC','Opponent','', 'THEM')}>+ Generic Opponent</button><p>Generic magnets only exist on this tactical frame.</p></div>}</aside></>}\n'''
    s = s[:start] + drawer + s[end:]

marker2 = "    {analysisOpen&&"
if "className=\"magnet-inspector\"" not in s:
    inspector = '''    {selectedMagnetId&&!presenting&&state.magnets.some(item=>item.id===selectedMagnetId)&&<aside className="magnet-inspector">{(()=>{const magnet=state.magnets.find(item=>item.id===selectedMagnetId)!;return <><header><div><span>SELECTED PLAYER</span><b>{magnet.name}</b></div><button onClick={()=>setSelectedMagnetId('')}><X/></button></header><label>Name<input value={magnet.name} onChange={e=>updateSelectedMagnet({name:e.target.value})}/></label><label>Number<input inputMode="numeric" value={magnet.number??''} onChange={e=>updateSelectedMagnet({number:e.target.value===''?null:Number(e.target.value)})}/></label><div className="inspector-team"><button className={magnet.team==='US'?'active':''} onClick={()=>updateSelectedMagnet({team:'US'})}>Our team</button><button className={magnet.team==='THEM'?'active':''} onClick={()=>updateSelectedMagnet({team:'THEM'})}>Opposition</button></div><button onClick={duplicateSelectedMagnet}>Duplicate</button><button className="danger" onClick={removeSelectedMagnet}>Remove from frame</button></>})()}</aside>}\n'''
    s = s.replace(marker2, inspector + marker2, 1)

s = s.replace("<g key={magnet.id} transform={`translate(${magnet.x} ${magnet.y})`}", "<g key={magnet.id} className={selectedMagnetId===magnet.id?'selected-magnet':''} transform={`translate(${magnet.x} ${magnet.y})`}")

idx = s.rfind('`')
css = r'''
/* Stage 8 Priority 3 — player handling */
.player-drawer-backdrop{position:fixed;inset:64px 0 0 0;background:rgba(0,0,0,.28);border:0;z-index:70}
.player-drawer{position:fixed!important;left:68px!important;top:64px!important;bottom:0!important;width:min(390px,calc(100vw - 68px))!important;z-index:80!important;background:#071923!important;border-right:1px solid #31505f!important;box-shadow:20px 0 50px rgba(0,0,0,.42)!important;padding:16px!important;display:flex!important;flex-direction:column!important;overflow:hidden!important}
.player-drawer header{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.player-drawer header span{color:#20b8ff;font-size:10px;font-weight:900;letter-spacing:.12em}.player-drawer h2{margin:3px 0;font-size:22px}.player-drawer p{margin:0;color:#8fa9b6;font-size:12px}.player-drawer header button{width:42px;height:42px;padding:0;justify-content:center}
.player-tabs{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin:14px 0 10px}.player-tabs button{min-height:42px}.player-tabs button.active{background:#109ee8!important;border-color:#50c7ff!important}
.player-search{width:100%;min-height:46px;border-radius:12px;border:1px solid #31505f;background:#0c2633;color:#fff;padding:0 13px;font-size:15px;outline:none}.player-search:focus{border-color:#20b8ff;box-shadow:0 0 0 3px rgba(32,184,255,.15)}
.quick-setups{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin:10px 0}.quick-setups button{min-height:40px;padding:6px!important;justify-content:center!important}
.player-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:10px}.player-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;overflow-y:auto;padding-right:3px;flex:1}.player-grid button{min-height:72px;display:grid!important;grid-template-columns:34px 1fr;grid-template-rows:auto auto;text-align:left;align-items:center}.player-grid button b{grid-row:1/3;width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:#153748}.player-grid button span{font-size:12px}.player-grid button small{font-size:10px;color:#8fa9b6}.player-grid button.selected{border-color:#20b8ff}.player-grid button.queued{background:#12384a!important;box-shadow:inset 0 0 0 2px #f6c945}.player-drawer footer{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding-top:12px}.player-drawer footer button{min-height:46px}.player-drawer footer .primary{background:#109ee8!important;border-color:#20b8ff!important}.player-drawer footer button:disabled{opacity:.4}.generic-actions{display:flex;flex-direction:column;gap:10px}
.magnet-inspector{position:fixed!important;right:14px!important;top:78px!important;width:280px!important;z-index:65!important;background:#071923!important;border:1px solid #31505f!important;border-radius:18px!important;padding:14px!important;box-shadow:0 22px 60px rgba(0,0,0,.45)!important;display:flex!important;flex-direction:column!important;gap:10px!important}.magnet-inspector header{display:flex;justify-content:space-between;align-items:center}.magnet-inspector header span{display:block;color:#20b8ff;font-size:9px;font-weight:900;letter-spacing:.11em}.magnet-inspector header b{font-size:16px}.magnet-inspector header button{width:38px;height:38px;padding:0;justify-content:center}.magnet-inspector label{display:flex;flex-direction:column;gap:5px;color:#9fb3be;font-size:11px;font-weight:800}.magnet-inspector input{min-height:42px;border-radius:10px;border:1px solid #31505f;background:#0c2633;color:#fff;padding:0 10px}.inspector-team{display:grid;grid-template-columns:1fr 1fr;gap:7px}.inspector-team button.active{background:#109ee8!important;border-color:#20b8ff!important}.magnet-inspector .danger{background:#451b23!important;border-color:#7c2d38!important;color:#ffdce1!important}.selected-magnet circle:first-of-type{stroke:#f6c945!important;stroke-width:1.8!important;filter:drop-shadow(0 0 3px rgba(246,201,69,.8))}
@media(max-width:760px){.player-drawer{left:58px!important;width:calc(100vw - 58px)!important}.player-grid{grid-template-columns:1fr}.magnet-inspector{right:8px!important;top:auto!important;bottom:100px!important;width:min(300px,calc(100vw - 74px))!important}.quick-setups{grid-template-columns:repeat(2,1fr)}}
'''
if idx >= 0 and 'Stage 8 Priority 3' not in s:
    s = s[:idx] + css + s[idx:]

p.write_text(s)
